mapper.select:
${pagingTop} SELECT picture_book_idx, picture_book_name, picture_book_subject, author, publisher, publish_year, isbn, picture_price, picture_count, keyword, category, desc_link, thumb_image, content, pay_yn, org_file_name, server_file_name, file_extension, file_size, add_id, add_date FROM PICTURE_BOOK WHERE pay_yn = #{pay_yn}
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND category = #{category}
ORDER BY picture_book_subject ASC ${pagingBottom}

SELECT COUNT(*) FROM PICTURE_BOOK WHERE pay_yn = #{pay_yn}
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND category = #{category}

mapper.update:
UPDATE PICTURE_BOOK SET picture_book_name = #{picture_book_name}, picture_book_subject = #{picture_book_subject}, author = #{author}, publisher = #{publisher}, publish_year = #{publish_year}, isbn = #{isbn}, picture_price = #{picture_price}, picture_count = #{picture_count}, keyword = #{keyword}, category = #{category}, desc_link = #{desc_link}, thumb_image = #{thumb_image}, content = #{content},
org_file_name = #{org_file_name}, server_file_name = #{server_file_name}, file_extension = #{file_extension}, file_size = #{file_size},
modify_id = #{modify_id}, modify_date = SYSDATE WHERE pay_yn = #{pay_yn} AND picture_book_idx = #{picture_book_idx}

mapper.delete:
DELETE FROM
	PICTURE_BOOK
WHERE
	pay_yn = #{pay_yn}
AND	picture_book_idx = #{picture_book_idx}

mapper.select:
		${pagingTop}
		SELECT
			a.picture_book_idx, b.picture_book_loan_idx, a.picture_book_subject, school_name,
			loan_start_date, loan_end_date, TO_CHAR(loan_start_date, 'yyyy') AS loan_year, TO_CHAR(loan_start_date, 'MM') AS loan_month, pay_yn,
			phone, school_tel, request_content, request_status, b.add_id, b.add_date,
			(substr(request_name,1,1) || lpad('*',length(request_name)-2,'*') || substr(request_name, length(request_name), 1)) AS request_name
		FROM
			PICTURE_BOOK a, PICTURE_BOOK_LOAN b
		WHERE
			a.picture_book_idx = b.picture_book_idx
		AND	pay_yn = #{pay_yn}
		
		AND	${search_type} LIKE '%'||#{search_text}||'%'
		
		
		AND	TO_CHAR(loan_start_date, 'yyyy') = #{loan_year}
		
		
		AND	TO_CHAR(loan_start_date, 'MM') = #{loan_month}
		
		
		AND	request_status = #{request_status}
		
		
		AND	b.add_id = #{add_id}
		
		ORDER BY b.add_date DESC

		${pagingBottom}

SELECT
	COUNT(*)
FROM
	PICTURE_BOOK a, PICTURE_BOOK_LOAN b
WHERE
	a.picture_book_idx = b.picture_book_idx
AND	pay_yn = #{pay_yn}

AND	${search_type} LIKE '%'||#{search_text}||'%'


AND	TO_CHAR(loan_start_date, 'yyyy') = #{loan_year}


AND	TO_CHAR(loan_start_date, 'MM') = #{loan_month}


AND	request_status = #{request_status}


AND	b.add_id = #{add_id}

SELECT
	COUNT(picture_book_loan_idx)
FROM
	PICTURE_BOOK_LOAN 
WHERE
	picture_book_idx = #{picture_book_idx}
AND TO_CHAR(loan_start_date, 'yyyy') = #{loan_year}
AND	TO_CHAR(loan_start_date, 'MM') = #{loan_month}

SELECT a.picture_book_idx, b.picture_book_loan_idx, a.picture_book_subject, request_name, school_name, loan_start_date, loan_end_date, TO_CHAR(loan_start_date, 'yyyy') AS loan_year, TO_CHAR(loan_start_date, 'MM') AS loan_month, pay_yn, phone, school_tel, request_content, request_status, b.add_id, b.add_date, b.delivery_location FROM PICTURE_BOOK a, PICTURE_BOOK_LOAN b WHERE a.picture_book_idx = b.picture_book_idx AND pay_yn = #{pay_yn}
AND b.add_id = #{add_id}
ORDER BY a.picture_book_subject ASC, b.loan_start_date ASC

SELECT
	count(*)
FROM
	PICTURE_BOOK a, PICTURE_BOOK_LOAN b
WHERE
	a.picture_book_idx = b.picture_book_idx
AND	TO_CHAR(b.loan_start_date,'yyyy-MM-dd') <= #{loan_end_date}
AND TO_CHAR(b.loan_end_date,'yyyy-MM-dd') >= #{loan_start_date}
AND a.picture_book_idx = #{picture_book_idx}

SELECT
	TO_CHAR(TO_DATE(max(b.loan_end_date), 'yyyy-MM-dd') + 5, 'yyyy-MM-dd') as loan_end_date
FROM
	PICTURE_BOOK a, PICTURE_BOOK_LOAN b
WHERE
	a.picture_book_idx = b.picture_book_idx
AND	TO_CHAR(b.loan_start_date,'yyyy-MM-dd') <= #{loan_end_date}
AND TO_CHAR(b.loan_end_date,'yyyy-MM-dd') >= #{loan_start_date}
AND a.picture_book_idx = #{picture_book_idx}
